<?php

namespace Database\Seeders;

use App\Share\Models\FitnessClass;
use Illuminate\Database\Seeder;

/**
 * Catalog 20 lớp, chuyển từ mock `fitness-web/src/mocks/classes.ts`.
 */
class FitnessClassesSeeder extends Seeder
{
    /**
     * Run the database seeds.
     */
    public function run(): void
    {
        foreach ($this->classes() as $class) {
            if (FitnessClass::query()->where('slug', $class['slug'])->exists()) {
                continue;
            }

            FitnessClass::query()->create([
                'slug' => $class['slug'],
                'category' => $class['category'],
                'name' => $class['name'],
                'vi' => ['description' => $class['vi']],
                'en' => ['description' => $class['en']],
            ]);
        }
    }

    /**
     * @return list<array<string, string>>
     */
    private function classes(): array
