            ['slug' => 'super-core', 'category' => 'core-pilates', 'name' => 'Super Core', 'en' => 'An intensified core class that challenges the abs, obliques and lower back with more dynamic, higher-intensity movements. Best suited for those with some core training experience who are ready to push further. Great for building deeper strength and stability at the centre of the body.', 'vi' => 'Lớp tập core cường độ cao, thử thách vùng bụng, liên sườn và lưng dưới với các động tác năng động hơn. Phù hợp với ai đã có nền tảng tập core và sẵn sàng thử thách bản thân nhiều hơn. Giúp xây dựng sức mạnh và sự vững vàng sâu hơn cho vùng trung tâm cơ thể.'],
            ['slug' => 'basic-pilates', 'category' => 'core-pilates', 'name' => 'Basic Pilates', 'en' => 'A foundational mat Pilates class focused on breath, alignment and controlled movement to build core strength and body awareness. Perfect for beginners or anyone wanting to revisit the fundamentals. A calm, low-impact way to strengthen from the inside out.', 'vi' => 'Lớp Pilates thảm căn bản, tập trung vào hơi thở, sự canh chỉnh và chuyển động có kiểm soát để xây dựng sức mạnh core và nhận thức cơ thể. Phù hợp cho người mới bắt đầu hoặc ai muốn ôn lại những nền tảng cơ bản. Một cách tập nhẹ nhàng, ít tác động để rèn luyện từ bên trong.'],
            ['slug' => 'pilates-flow', 'category' => 'core-pilates', 'name' => 'Pilates Flow', 'en' => 'A dynamic mat Pilates class linking movements into a continuous, flowing sequence to build strength, flexibility and coordination. Suited to those with some Pilates experience who enjoy a more fluid pace. Combines the precision of Pilates with the rhythm of movement flow.', 'vi' => 'Lớp Pilates thảm với nhịp độ chuyển động liên tục, kết nối các động tác thành chuỗi liền mạch để xây dựng sức mạnh, sự dẻo dai và khả năng phối hợp. Phù hợp với ai đã có nền tảng Pilates và yêu thích nhịp tập uyển chuyển. Kết hợp sự chính xác của Pilates cùng nhịp điệu của chuyển động liên tục.'],
            ['slug' => 'yoga-flow', 'category' => 'yoga-sound', 'name' => 'Yoga Flow', 'en' => 'A dynamic yoga class linking breath with movement through a flowing sequence of poses. Suited to anyone wanting to build strength, flexibility and mindfulness in one practice. Welcoming for newer and experienced yogis alike, offering an energising, moving meditation.', 'vi' => 'Lớp yoga với nhịp độ chuyển động liên tục, kết nối hơi thở cùng các tư thế nối tiếp nhau. Phù hợp với ai muốn xây dựng sức mạnh, sự dẻo dai và sự tĩnh tâm trong cùng một buổi tập. Chào đón cả người mới lẫn người đã quen với yoga, mang đến cảm giác như một thiền động đầy năng lượng.'],
            ['slug' => 'yogalates', 'category' => 'yoga-sound', 'name' => 'Yogalates', 'en' => 'A blend of yoga and Pilates, bringing together mindful breathwork and flowing poses with core-strengthening, controlled movement. Ideal for anyone wanting the calm and flexibility of yoga alongside the strength and stability of Pilates. A well-rounded practice for both body and mind.', 'vi' => 'Sự kết hợp giữa yoga và Pilates, mang đến hơi thở tĩnh tâm và các tư thế nối tiếp cùng những chuyển động kiểm soát giúp tăng cường core. Phù hợp với ai muốn có được sự tĩnh tại, dẻo dai của yoga cùng sức mạnh và ổn định của Pilates trong một buổi tập. Một bộ môn toàn diện cho cả cơ thể lẫn tâm trí.'],
            ['slug' => 'deep-stretch-sound', 'category' => 'yoga-sound', 'name' => 'Deep Stretch + Sound Healing', 'en' => 'A slow, deeply restorative stretch class paired with the calming sounds of singing bowls and gentle instrumental healing music. Perfect for anyone wanting to release tension, improve flexibility and unwind body and mind together. A soothing way to close out a busy day or week.', 'vi' => 'Lớp giãn cơ sâu, chậm rãi kết hợp cùng âm thanh trị liệu từ chuông xoay và nhạc cụ nhẹ nhàng. Phù hợp với ai muốn giải phóng căng thẳng, cải thiện độ dẻo dai và thư giãn cả cơ thể lẫn tâm trí. Một cách nhẹ nhàng để khép lại một ngày hay một tuần bận rộn.'],
            ['slug' => 'yin-yoga-sound', 'category' => 'yoga-sound', 'name' => 'Yin Yoga + Sound Healing', 'en' => 'A slow-paced yoga practice where poses are held for several minutes to release deep tension in the connective tissue, accompanied by live sound healing. Suited to anyone seeking deep relaxation, improved flexibility and a meditative reset. Ideal for those wanting to slow down and reconnect with themselves.', 'vi' => 'Bộ môn yoga với nhịp độ chậm, các tư thế được giữ trong vài phút để giải phóng căng thẳng sâu trong mô liên kết, kết hợp cùng âm thanh trị liệu trực tiếp. Phù hợp với ai đang tìm kiếm sự thư giãn sâu, cải thiện độ dẻo dai và một khoảng lặng để tái tạo năng lượng. Thích hợp cho những ai muốn chậm lại và kết nối lại với chính mình.'],
            ['slug' => 'aerial-yin-yoga-sound', 'category' => 'yoga-sound', 'name' => 'Aerial Yin Yoga + Sound Healing', 'en' => 'A gentle Yin Yoga practice using a soft hammock to support deep stretches and spinal traction, paired with immersive sound healing. Great for anyone curious about aerial support to deepen their stretch and ease tension along the spine. A unique, deeply restorative experience for body and mind.', 'vi' => 'Bộ môn Yin Yoga nhẹ nhàng sử dụng võng lụa hỗ trợ các động tác giãn sâu và kéo giãn cột sống, kết hợp cùng âm thanh trị liệu. Phù hợp với ai tò mò muốn trải nghiệm sự hỗ trợ của võng để giãn sâu hơn và giải tỏa căng thẳng dọc cột sống. Một trải nghiệm phục hồi độc đáo cho cả cơ thể và tâm trí.'],
            ['slug' => 'low-hammock-stretch-sound', 'category' => 'yoga-sound', 'name' => 'Low Hammock Stretch + Sound Healing', 'en' => 'A gentle, supported stretch class using a low hammock close to the ground to ease into deep stretches with minimal effort. Paired with calming sound healing, it\'s ideal for anyone wanting a restorative, low-intensity session to release tension. Suitable for all levels, including those new to aerial support.', 'vi' => 'Lớp giãn cơ nhẹ nhàng với sự hỗ trợ của võng thấp sát mặt sàn, giúp đi sâu vào các động tác giãn cơ mà không cần nhiều sức lực. Kết hợp cùng âm thanh trị liệu, đây là lựa chọn lý tưởng cho ai muốn một buổi tập phục hồi, cường độ nhẹ để giải phóng căng thẳng. Phù hợp với mọi cấp độ, kể cả người mới làm quen với võng.'],
            ['slug' => 'basic-barre', 'category' => 'barre', 'name' => 'Basic Barre', 'en' => 'An introductory barre class combining ballet-inspired movements, small isolated pulses and light resistance to build strength and improve posture. Ideal for beginners or anyone wanting to learn proper form and alignment from the start. A low-impact way to build a strong foundation.', 'vi' => 'Lớp Barre căn bản, kết hợp các động tác lấy cảm hứng từ ballet, chuyển động nhỏ lặp lại và kháng lực nhẹ để xây dựng sức mạnh và cải thiện tư thế. Phù hợp cho người mới bắt đầu hoặc ai muốn học đúng kỹ thuật và sự canh chỉnh ngay từ đầu. Một cách tập ít tác động để xây dựng nền tảng vững chắc.'],
            ['slug' => 'barre-burn', 'category' => 'barre', 'name' => 'Barre Burn', 'en' => 'A higher-intensity barre class that layers in more repetitions, holds and resistance to challenge strength and endurance. Best suited for those with some barre experience wanting a more intense session. Combines barre\'s precision with an added element of stamina-building challenge.', 'vi' => 'Lớp Barre với cường độ cao hơn, kết hợp nhiều lần lặp lại, giữ tư thế và kháng lực để thử thách sức mạnh và sức bền. Phù hợp với ai đã có nền tảng Barre và muốn một buổi tập cường độ mạnh hơn. Kết hợp sự chính xác của Barre cùng yếu tố thử thách sức bền.'],
            ['slug' => 'barre-flow', 'category' => 'barre', 'name' => 'Barre Flow', 'en' => 'A barre class that moves through sequences with a more continuous, flowing rhythm, blending strength work with fluid transitions. Suited to anyone who enjoys a dynamic pace while still building strength and tone. A great middle ground between structured barre technique and rhythmic movement.', 'vi' => 'Lớp Barre với nhịp độ chuyển động liên tục và mượt mà hơn, kết hợp các bài tập sức mạnh cùng những chuyển tiếp linh hoạt. Phù hợp với ai thích nhịp độ tập năng động nhưng vẫn muốn xây dựng sức mạnh và sự săn chắc. Là lựa chọn cân bằng giữa kỹ thuật Barre bài bản và chuyển động theo nhịp điệu.'],
            ['slug' => 'guided-meditation-sound', 'category' => 'meditation-sound', 'name' => 'Guided Meditation + Sound Healing', 'en' => 'A seated or lying meditation practice guided through breath and visualisation, layered with live sound healing to deepen relaxation. Ideal for anyone wanting to quiet the mind, ease stress and reconnect with the present moment. No experience necessary — just an open mind and a willingness to slow down.', 'vi' => 'Buổi thiền định có hướng dẫn qua hơi thở và hình dung, kết hợp cùng âm thanh trị liệu trực tiếp để đi sâu vào trạng thái thư giãn. Phù hợp với ai muốn làm dịu tâm trí, giảm căng thẳng và trở về với hiện tại. Không cần kinh nghiệm — chỉ cần một tâm thế cởi mở và sẵn sàng chậm lại.'],
            ['slug' => 'relaxing-sound-healing', 'category' => 'meditation-sound', 'name' => 'Relaxing Sound Healing', 'en' => 'A fully immersive sound bath using singing bowls and other healing instruments to guide the body into deep rest. Perfect for anyone seeking stress relief, better sleep, or simply a quiet space to reset. Lie back, breathe and let the sound do the rest.', 'vi' => 'Buổi tắm âm thanh trọn vẹn với chuông xoay và các nhạc cụ trị liệu khác, đưa cơ thể vào trạng thái nghỉ ngơi sâu. Phù hợp với ai đang tìm kiếm sự giải tỏa căng thẳng, giấc ngủ ngon hơn, hoặc đơn giản là một không gian yên tĩnh để tái tạo năng lượng. Chỉ cần nằm xuống, hít thở và để âm thanh dẫn dắt.'],
            ['slug' => 'zumba', 'category' => 'dance-cardio', 'name' => 'Zumba', 'en' => 'A high-energy dance fitness class set to upbeat Latin and international music, blending easy-to-follow choreography with cardio conditioning. Perfect for anyone who wants to move, sweat and have fun without it feeling like a traditional workout. No dance experience needed — just bring your energy.', 'vi' => 'Lớp fitness kết hợp khiêu vũ đầy năng lượng theo nhạc Latin và quốc tế sôi động, với các bước nhảy dễ theo cùng bài tập cardio. Phù hợp với ai muốn vận động, đổ mồ hôi và tận hưởng niềm vui mà không cảm thấy như đang “tập luyện” theo cách truyền thống. Không cần biết nhảy — chỉ cần mang theo năng lượng của bạn.'],
            ['slug' => 'cardio-dance', 'category' => 'dance-cardio', 'name' => 'Cardio Dance', 'en' => 'A fun, fast-paced dance class combining simple choreography with cardio intervals to get the heart rate up. Suited to anyone who enjoys music-driven movement and wants an engaging way to build endurance. A joyful alternative to traditional cardio training.', 'vi' => 'Lớp khiêu vũ vui nhộn, nhịp độ nhanh kết hợp các bước nhảy đơn giản cùng các khoảng cardio để tăng nhịp tim. Phù hợp với ai yêu thích vận động theo nhạc và muốn một cách thú vị để xây dựng sức bền. Một lựa chọn đầy niềm vui thay cho cách tập cardio truyền thống.'],
        ];
